input.content:
#!/usr/bin/env python3
"""Static check: CVE-2016-2184 guard present and ordered before endpoint use.

Reads sound/usb/quirks.c from the current working directory (the clean
validation checkout after generated.patch was applied) and asserts:
  1. create_fixed_stream_quirk binds altsd = get_iface_desc(alts);
  2. a 'bNumEndpoints < 1' guard exists after that binding;
  3. the guard frees fp and rate_table and returns -EINVAL;
  4. the guard precedes every get_endpoint(alts, 0) / snd_usb_parse_datainterval
     use inside the function.
Exit 0 on success, 1 on failure. This is a static structural check only.
"""
import re
import sys

path = "sound/usb/quirks.c"
try:
    text = open(path, encoding="utf-8", errors="replace").read()
except OSError as exc:
    print(f"FAIL: cannot read {path}: {exc}")
    sys.exit(1)

start = text.find("create_fixed_stream_quirk(struct snd_usb_audio")
if start < 0:
    print("FAIL: create_fixed_stream_quirk not found")
    sys.exit(1)
# function body ends at the next top-level closing brace line
end = text.find("\n}\n", start)
if end < 0:
    end = len(text)
body = text[start:end]

def idx(needle):
    return body.find(needle)

bind = idx("altsd = get_iface_desc(alts);")
guard = idx("bNumEndpoints < 1")
datainterval = idx("snd_usb_parse_datainterval(chip, alts)")
getep = idx("get_endpoint(alts, 0)->wMaxPacketSize")

errors = []
if bind < 0:
    errors.append("altsd binding missing")
if guard < 0:
    errors.append("bNumEndpoints < 1 guard missing")
if bind >= 0 and guard >= 0 and not (bind < guard):
    errors.append("guard does not follow altsd binding")
for token in ("kfree(fp);", "kfree(rate_table);", "return -EINVAL;"):
    if token not in body:
        errors.append(f"cleanup token missing: {token}")
# find the guard block and verify cleanup is inside it
if guard >= 0:
    block = body[guard:guard + 220]
    for token in ("kfree(fp);", "kfree(rate_table);", "return -EINVAL;"):
        if token not in block:
            errors.append(f"cleanup token not in guard block: {token}")
if datainterval < 0:
    errors.append("snd_usb_parse_datainterval(chip, alts) not found")
elif guard >= 0 and not (guard < datainterval):
    errors.append("guard does not precede snd_usb_parse_datainterval")
if getep < 0:
    errors.append("get_endpoint(alts, 0)->wMaxPacketSize not found")
elif guard >= 0 and not (guard < getep):
    errors.append("guard does not precede get_endpoint(alts, 0)")

if errors:
    print("FAIL: " + "; ".join(errors))
    sys.exit(1)
print("PASS: bNumEndpoints guard present, ordered before endpoint dereferences, with fp/rate_table cleanup")
sys.exit(0)

